/* charts */
.charts { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 14px; }
.charts .wide { grid-column: 1 / -1; }
figure { margin: 0; }
figcaption { font-weight: 600; margin-bottom: 10px; display: flex; gap: 8px; align-items: baseline; }
figcaption small { color: var(--faint); font-weight: 400; }
.chart svg { display: block; overflow: visible; }
.chart text { fill: var(--text); font-size: 12px; }
.chart text.val { fill: var(--muted); font-variant-numeric: tabular-nums; }
.chart text.big { font-size: 22px; font-weight: 650; }
.chart text.sm { fill: var(--muted); font-size: 11px; }
.chart .hit { cursor: pointer; }
.chart .hit:hover .fill, .chart .hit:focus-visible .fill { filter: brightness(1.1); }
.chart .hit:focus-visible { outline: none; }
.chart .hit:focus-visible .fill, .chart .hit:focus-visible path { stroke: var(--accent); stroke-width: 2; }
.chart .dim { opacity: .3; }
.chart .track { fill: var(--panel-2); }
.donut-wrap { display: flex; align-items: center; gap: 18px; flex-wrap: wrap; }
.legend { display: grid; gap: 6px; }
.legend button { display: flex; align-items: center; gap: 8px; border: 0; background: none; padding: 2px 4px; text-align: left; border-radius: 5px; }
