.bg-high { background: var(--high); } .bg-medium { background: var(--medium); } .bg-low { background: var(--low); }
.bg-assets { background: var(--c-assets); } .bg-strings { background: var(--c-strings); } .bg-files { background: var(--c-files); } .bg-duplicates { background: var(--c-duplicates); }
.bg-k-app { background: var(--k-app); } .bg-k-ext { background: var(--k-ext); } .bg-k-lib { background: var(--k-lib); } .bg-k-test { background: var(--k-test); } .bg-k-other { background: var(--k-other); }

/* graph */
.graph { overflow-x: auto; position: relative; }
