.toolbar { display: flex; gap: 10px; align-items: center; padding: 12px; border-bottom: 1px solid var(--border); flex-wrap: wrap; }
.search { flex: 1 1 360px; position: relative; min-width: 0; }
.search input { width: 100%; font: 13px var(--mono); color: var(--text); background: var(--panel-2); border: 1px solid var(--border); border-radius: 8px; padding: 8px 10px 8px 30px; }
.search input[aria-invalid="true"] { border-color: var(--high); }
.search::before { content: ""; position: absolute; left: 11px; top: 50%; width: 9px; height: 9px; border: 2px solid var(--faint); border-radius: 50%; transform: translateY(-62%); }
.search::after { content: ""; position: absolute; left: 20px; top: 58%; width: 2px; height: 6px; background: var(--faint); transform: rotate(-45deg); }
.count { color: var(--muted); font-variant-numeric: tabular-nums; white-space: nowrap; }
.count b { color: var(--text); }
.chips { display: flex; gap: 6px; flex-wrap: wrap; padding: 0 12px; }
.chips:not(:empty) { padding: 8px 12px; border-bottom: 1px solid var(--border); }
.chip { display: inline-flex; align-items: center; gap: 6px; background: var(--accent-soft); color: var(--text); border: 0; border-radius: 999px; padding: 3px 10px; font-size: 12px; }
.chip b { font-weight: 600; color: var(--muted); }
.scroller { height: min(70vh, 760px); overflow: auto; position: relative; outline-offset: -2px; }
table { width: 100%; border-collapse: separate; border-spacing: 0; table-layout: fixed; }
thead th { position: sticky; top: 0; z-index: 1; background: var(--panel-2); border-bottom: 1px solid var(--border); text-align: left; font-size: 12px; font-weight: 600; color: var(--muted); padding: 0; height: 34px; }
thead th button { all: unset; display: flex; align-items: center; gap: 4px; width: 100%; height: 34px; padding: 0 10px; box-sizing: border-box; cursor: pointer; }
thead th button:focus-visible { outline: 2px solid var(--accent); outline-offset: -2px; }
thead th[aria-sort] button { color: var(--text); }
thead th .ar { font-size: 10px; }
thead th.num button { justify-content: flex-end; }
tbody tr { height: 36px; cursor: pointer; }
tbody tr.spacer { height: auto; cursor: default; }
tbody tr.spacer td { padding: 0; border: 0; }
tbody td { padding: 0 10px; border-bottom: 1px solid var(--border); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; height: 36px; max-width: 0; }
tbody tr:hover td { background: var(--panel-2); }
tbody tr.active td { background: var(--sel); }
tbody tr:focus { outline: none; }
tbody tr:focus-visible td { box-shadow: inset 0 2px 0 var(--accent), inset 0 -2px 0 var(--accent); }
td.num { text-align: right; font-variant-numeric: tabular-nums; }
td .base { font-family: var(--mono); font-size: 12.5px; }
td .dir { font-family: var(--mono); font-size: 12px; color: var(--faint); margin-left: 6px; }
td.reason { color: var(--muted); }
td .more { color: var(--accent); font-size: 11px; margin-left: 6px; }
.kind { display: inline-flex; align-items: center; gap: 7px; }
.dot { width: 8px; height: 8px; border-radius: 50%; flex: none; display: inline-block; }
.badge { display: inline-block; padding: 1px 8px; border-radius: 999px; font-size: 11.5px; font-weight: 600; line-height: 18px; }
.b-high { color: var(--high); background: var(--high-bg); } .b-medium { color: var(--medium); background: var(--medium-bg); } .b-low { color: var(--low); background: var(--low-bg); }
.b-plain { color: var(--muted); background: var(--panel-2); }
.empty { padding: 40px; text-align: center; color: var(--muted); }

/* lower */
.lower { display: grid; grid-template-columns: minmax(0, 1.4fr) minmax(0, 1fr) minmax(0, 1fr); gap: 14px; align-items: start; }
.list { margin: 0; padding: 0; list-style: none; max-height: 340px; overflow: auto; }
.list li { padding: 7px 0; border-bottom: 1px solid var(--border); display: flex; gap: 8px; align-items: baseline; min-width: 0; }
.list li:last-child { border-bottom: 0; }
.list .grow { min-width: 0; flex: 1; overflow-wrap: anywhere; }
.list .num { color: var(--muted); font-variant-numeric: tabular-nums; }
button.link { border: 0; background: none; padding: 0; color: var(--accent); text-align: left; font: 12.5px var(--mono); overflow-wrap: anywhere; }
.sub-h { font-size: 12px; color: var(--muted); text-transform: uppercase; letter-spacing: .05em; margin: 10px 0 4px; }
.sub-h:first-child { margin-top: 0; }
.legend-dl { margin: 0; display: grid; gap: 10px; }
.legend-dl dt { display: inline; }
.legend-dl dd { margin: 3px 0 0; color: var(--muted); }
.muted { color: var(--muted); }

/* drawer */
.drawer { position: fixed; top: 0; right: 0; bottom: 0; width: min(520px, 100vw); background: var(--panel); border-left: 1px solid var(--border); box-shadow: -8px 0 30px rgba(0,0,0,.18); z-index: 20; display: flex; flex-direction: column; }
.drawer[hidden] { display: none; }
.drawer header { display: flex; gap: 10px; align-items: flex-start; padding: 16px 18px; border-bottom: 1px solid var(--border); }
.drawer header h3 { font-size: 16px; flex: 1; overflow-wrap: anywhere; }
.drawer .body { padding: 16px 18px; overflow: auto; display: grid; grid-template-columns: minmax(0, 1fr); gap: 16px; align-content: start; }
.drawer .badges { display: flex; gap: 6px; flex-wrap: wrap; }
.drawer dl { margin: 0; display: grid; grid-template-columns: 90px minmax(0, 1fr); gap: 6px 12px; }
.drawer dt { color: var(--muted); }
.drawer dd { margin: 0; overflow-wrap: anywhere; }
.drawer ol { margin: 0; padding-left: 20px; display: grid; gap: 4px; overflow-wrap: anywhere; }
.drawer .sites, .drawer .sites ul { margin: 0; padding: 0; list-style: none; display: grid; gap: 6px; overflow-wrap: anywhere; }
.drawer .sites ul { padding-left: 14px; margin-top: 4px; border-left: 2px solid var(--border); }
.drawer h4 { margin: 0 0 6px; font-size: 12px; text-transform: uppercase; letter-spacing: .05em; color: var(--muted); }
.drawer .btns { display: flex; gap: 8px; flex-wrap: wrap; }
.drawer pre { margin: 0; padding: 8px 10px; background: var(--panel-2); border-radius: 7px; font: 12.5px var(--mono); white-space: pre-wrap; overflow-wrap: anywhere; }
.tip { position: fixed; z-index: 30; pointer-events: none; background: var(--panel); color: var(--text); border: 1px solid var(--border); border-radius: 8px; padding: 9px 11px; box-shadow: 0 6px 24px rgba(0,0,0,.18); font-size: 12.5px; max-width: 340px; }
.tip b { display: block; margin-bottom: 4px; }
.tip .row { color: var(--muted); }
.tip .row span { color: var(--text); }
.toast { position: fixed; left: 50%; bottom: 24px; transform: translateX(-50%) translateY(20px); background: var(--text); color: var(--bg); padding: 8px 14px; border-radius: 8px; opacity: 0; transition: .18s; pointer-events: none; z-index: 40; }
.toast.show { opacity: 1; transform: translateX(-50%); }
.sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }

@media (max-width: 1100px) {
  .finder { grid-template-columns: minmax(0, 1fr); }
  .facets { display: none; position: static; max-height: none; }
  .finder.show-facets .facets { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 12px; }
  .finder.show-facets .facet + .facet { margin-top: 0; padding-top: 0; border-top: 0; }
  .only-narrow { display: inline-block; }
  .stats { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .charts, .lower { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (max-width: 640px) {
  .wrap { padding: 0 16px; }
  .stats { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .charts, .lower { grid-template-columns: minmax(0, 1fr); }
  col.c-reason, th.c-reason, td.reason, col.c-module, th.c-module, td.mod { display: none; }
}
@media (prefers-reduced-motion: reduce) { .toast { transition: none; } }
</style>
</head>
<body>
<pre id="js-errors" hidden></pre>
<script>
window.onerror = function (msg, src, line, col) { var p = document.getElementById('js-errors'); if (p) { p.hidden = false; p.textContent += 'JS error: ' + msg + ' @' + line + ':' + col + '\n'; } };
window.addEventListener('unhandledrejection', function (e) { window.onerror('unhandled rejection: ' + (e.reason && e.reason.message || e.reason), '', 0, 0); });
</script>
<header class="top">
  <div class="wrap top-inner">
    <div class="brand">
      <h1><span class="logo" aria-hidden="true"></span>{{TOOL}} <span class="sub">report</span></h1>
      <code class="root" id="root" title="{{ROOT}}">{{ROOT}}</code>
    </div>
    <div class="actions">
      <button id="btn-json" type="button">Export filtered JSON</button>
      <button id="btn-csv" type="button">Export CSV</button>
      <button id="btn-ignore" type="button" title="Copy .xcpurgeignore entries for the findings currently shown">Copy .xcpurgeignore entries</button>
      <button id="btn-theme" type="button" aria-label="Color theme: automatic. Activate to change.">Theme: auto</button>
    </div>
  </div>
  <dl class="wrap stats">
    <div><dt>Findings</dt><dd id="s-findings">–</dd></div>
    <div><dt>Reclaimable <small>high + medium</small></dt><dd id="s-bytes">–</dd></div>
    <div><dt>Modules</dt><dd id="s-modules">–</dd></div>
    <div><dt>Files scanned</dt><dd id="s-files">{{FILES}}</dd></div>
    <div><dt>Scanned</dt><dd class="small"><time id="s-date" datetime="{{DATE}}">{{DATE}}</time></dd></div>
    <div><dt>Version</dt><dd class="small" id="s-version">{{VERSION}}</dd></div>
  </dl>
</header>
<main class="wrap">
  <section aria-labelledby="h-overview">
    <h2 id="h-overview">Overview <span class="hint">· click a bar or segment to filter</span></h2>
    <div class="charts">
      <figure class="card"><figcaption>Findings by kind</figcaption><div id="ch-kind" class="chart"></div></figure>
      <figure class="card"><figcaption>By confidence</figcaption><div id="ch-conf" class="chart"></div></figure>
      <figure class="card"><figcaption>Reclaimable by module <small>high + medium</small></figcaption><div id="ch-bytes" class="chart"></div></figure>
      <figure class="card wide"><figcaption>Findings by module and category</figcaption><div id="ch-stack" class="chart"></div></figure>
    </div>
  </section>

  <section class="card" aria-labelledby="h-graph">
    <div class="sec-head">
      <h2 id="h-graph">Module graph</h2>
      <div class="legend-row" aria-label="Graph legend">
        <span><i class="sw bg-k-app"></i>app</span><span><i class="sw bg-k-ext"></i>extension</span><span><i class="sw bg-k-lib"></i>library / package</span><span><i class="sw bg-k-test"></i>test</span>
        <span>── depends on</span><span>- - embeds</span><span>size = findings</span>
      </div>
    </div>
    <div id="graph" class="graph"></div>
  </section>

  <section aria-labelledby="h-findings">
    <h2 id="h-findings">Findings</h2>
    <div class="finder" id="finder">
      <aside id="facets" class="facets" aria-label="Filters"></aside>
      <div class="results">
        <div class="toolbar">
          <button id="btn-filters" class="only-narrow" type="button" aria-expanded="false" aria-controls="facets">Filters</button>
          <div class="search"><input id="q" type="search" autocomplete="off" spellcheck="false" aria-label="Search findings. Supports kind:, conf:, module:, path:, name:, cat: tokens and /regex/" placeholder="Search…  kind:unused-asset conf:high module:App path:Assets /regex/"></div>
          <span id="count" class="count" aria-live="polite"></span>
          <button id="btn-clear" type="button">Clear</button>
        </div>
        <div id="chips" class="chips"></div>
        <div id="scroller" class="scroller" tabindex="0" aria-label="Findings table. Arrow keys move between rows, Enter opens details.">
          <table id="tbl" aria-label="Findings">
            <colgroup><col style="width:150px"><col style="width:92px"><col class="c-module" style="width:130px"><col style="width:20%"><col style="width:28%"><col style="width:84px"><col class="c-reason"></colgroup>
            <thead><tr>
              <th scope="col" data-sort="kind"><button type="button">Kind</button></th>
              <th scope="col" data-sort="conf"><button type="button">Confidence</button></th>
              <th scope="col" class="c-module" data-sort="module"><button type="button">Module</button></th>
              <th scope="col" data-sort="name"><button type="button">Name</button></th>
              <th scope="col" data-sort="path"><button type="button">Path</button></th>
              <th scope="col" class="num" data-sort="size"><button type="button">Size</button></th>
              <th scope="col" class="c-reason" data-sort="reasons"><button type="button">Reasons</button></th>
            </tr></thead>
            <tbody id="rows"></tbody>
          </table>
          <div id="empty" class="empty" hidden>No findings match the current filters.</div>
        </div>
      </div>
    </div>
  </section>

  <div class="lower">
    <section class="card" aria-labelledby="h-dyn"><h2 id="h-dyn">Dynamic lookups</h2><div id="dyn"></div></section>
    <section class="card" aria-labelledby="h-diag"><h2 id="h-diag">Diagnostics</h2><div id="diag"></div></section>
    <section class="card" aria-labelledby="h-legend">
      <h2 id="h-legend">Confidence legend</h2>
      <dl class="legend-dl">
        <div><dt><span class="badge b-high">high</span></dt><dd>No reference found anywhere visible to the owning module. Safe to remove after a quick look.</dd></div>
        <div><dt><span class="badge b-medium">medium</span></dt><dd>Only weak evidence of use (case-insensitive match, comment, unusual file). Review before removing.</dd></div>
        <div><dt><span class="badge b-low">low</span></dt><dd>Possibly used at runtime, e.g. a name built dynamically. Informational; verify by hand.</dd></div>
      </dl>
    </section>
  </div>
</main>

<aside id="drawer" class="drawer" role="dialog" aria-modal="false" aria-labelledby="d-title" hidden>
  <header><h3 id="d-title"></h3><button id="d-close" type="button" aria-label="Close details">✕</button></header>
  <div class="body" id="d-body"></div>
</aside>
<div id="tip" class="tip" role="tooltip" hidden></div>
<div id="toast" class="toast" role="status" aria-live="polite"></div>

<script id="xcpurge-data" type="application/json">{{DATA}}</script>
<script>
(() => {
'use strict';
const t0 = performance.now();
const $ = (s, r = document) => r.querySelector(s);
const timings = {};
const D = JSON.parse($('#xcpurge-data').textContent || '{}');
timings.parse = performance.now() - t0;
const F = Array.isArray(D.findings) ? D.findings : [];
const MODULES = Array.isArray(D.modules) ? D.modules : [];
const N = F.length;
const CATS = ['assets', 'strings', 'files', 'duplicates'];
const CONFS = ['high', 'medium', 'low'];
const CONF_RANK = { high: 0, medium: 1, low: 2 };

const kebab = s => String(s).replace(/[A-Z]/g, c => '-' + c.toLowerCase());
const ESC = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' };
const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => ESC[c]);
const fmt = n => Number(n).toLocaleString('en-US');
const human = b => { b = Number(b) || 0; const u = ['B', 'KB', 'MB', 'GB']; let i = 0; while (b >= 1024 && i < u.length - 1) { b /= 1024; i++; } return i ? (Math.round(b * 10) / 10) + ' ' + u[i] : b + ' B'; };
const trunc = (s, n) => { s = String(s); n = Math.max(3, Math.floor(n)); return s.length > n ? s.slice(0, n - 1) + '…' : s; };
const base = p => { const i = p.lastIndexOf('/'); return i < 0 ? p : p.slice(i + 1); };
const dirOf = p => { const i = p.lastIndexOf('/'); return i < 0 ? '' : p.slice(0, i + 1); };
const loc = f => f.path + (f.line != null ? ':' + f.line : '');
const kindClass = k => ({ app: 'k-app', appClip: 'k-app', watchApp: 'k-app', appExtension: 'k-ext', unitTest: 'k-test', uiTest: 'k-test',
  framework: 'k-lib', staticLib: 'k-lib', packageLibrary: 'k-lib', packageExecutable: 'k-lib', macro: 'k-lib', plugin: 'k-lib' })[k] || 'k-other';
const DYN_RE = /dynamically at (\S+?):(\d+)/g;

// ---- index (built once) ----
const LNAME = new Array(N), LPATH = new Array(N), LMOD = new Array(N), LREAS = new Array(N), HAY = new Array(N);
const kindCat = {};
for (let i = 0; i < N; i++) {
  const f = F[i];
  f.reasons = Array.isArray(f.reasons) ? f.reasons : [];
  LNAME[i] = (f.name || '').toLowerCase();
  LPATH[i] = loc(f).toLowerCase();
  LMOD[i] = String(f.module).toLowerCase();
  LREAS[i] = f.reasons.join('\n').toLowerCase();
  HAY[i] = LNAME[i] + '\n' + LPATH[i] + '\n' + LMOD[i] + '\n' + LREAS[i];
  if (!kindCat[f.kind]) kindCat[f.kind] = f.category;
}
const KEBAB_TO_KIND = {};
const FACETS = [
  { key: 'cat', label: 'Category', get: f => f.category },
  { key: 'kind', label: 'Kind', get: f => f.kind, show: kebab, hash: kebab },
  { key: 'conf', label: 'Confidence', get: f => f.confidence },
  { key: 'mod', label: 'Module', get: f => f.module },
];
for (const fc of FACETS) {
  const counts = new Map();
  for (let i = 0; i < N; i++) { const v = fc.get(F[i]); counts.set(v, (counts.get(v) || 0) + 1); }
  let vals = [...counts.keys()];
  if (fc.key === 'cat') vals.sort((a, b) => CATS.indexOf(a) - CATS.indexOf(b));
  else if (fc.key === 'conf') vals.sort((a, b) => CONF_RANK[a] - CONF_RANK[b]);
  else vals.sort((a, b) => counts.get(b) - counts.get(a) || (a < b ? -1 : 1));
  fc.values = vals; fc.total = counts; fc.index = new Map(vals.map((v, i) => [v, i]));
  fc.codes = new Uint16Array(N);
  for (let i = 0; i < N; i++) fc.codes[i] = fc.index.get(fc.get(F[i]));
  fc.sel = new Set();
}
for (const k of FACETS[1].values) KEBAB_TO_KIND[kebab(k)] = k;
const ignoreEntry = f => {
  if (f.name && f.category === 'assets' && f.kind === 'unusedAsset') return 'asset:' + f.name;
  if (f.name && f.category === 'strings' && f.kind !== 'dynamicLookup') return 'string:' + f.name;
  return f.path;
};
const dynSites = f => { const out = []; for (const r of f.reasons) for (const m of r.matchAll(DYN_RE)) out.push({ file: m[1], line: +m[2] }); return out; };
const dynFindings = [];
for (let i = 0; i < N; i++) if (F[i].kind === 'dynamicLookup') dynFindings.push(i);
timings.index = performance.now() - t0 - timings.parse;

// ---- sorting ----
const cmpStr = (a, b) => a < b ? -1 : a > b ? 1 : 0;
const SORTS = {
  kind: (a, b) => cmpStr(F[a].kind, F[b].kind),
  conf: (a, b) => CONF_RANK[F[a].confidence] - CONF_RANK[F[b].confidence],
  module: (a, b) => cmpStr(LMOD[a], LMOD[b]),
  name: (a, b) => cmpStr(LNAME[a] || LPATH[a], LNAME[b] || LPATH[b]),
  path: (a, b) => cmpStr(LPATH[a], LPATH[b]),
  size: (a, b) => (F[a].sizeBytes || 0) - (F[b].sizeBytes || 0),
  reasons: (a, b) => cmpStr(LREAS[a], LREAS[b]),
};
const orderCache = {};
function order(key) {
  if (!orderCache[key]) {
    const a = new Int32Array(N); for (let i = 0; i < N; i++) a[i] = i;
    if (SORTS[key]) a.sort((x, y) => SORTS[key](x, y) || x - y);
    orderCache[key] = a;
  }
  return orderCache[key];
}

// ---- query ----
const FIELD = {
  kind: { arr: null, norm: v => v.replace(/-/g, ''), test: (i, v) => F[i].kind.toLowerCase().includes(v), raw: i => F[i].kind },
  conf: { test: (i, v) => F[i].confidence.startsWith(v), raw: i => F[i].confidence },
  cat: { test: (i, v) => F[i].category.startsWith(v), raw: i => F[i].category },
  module: { test: (i, v) => LMOD[i].includes(v), raw: i => F[i].module },
  path: { test: (i, v) => LPATH[i].includes(v), raw: i => loc(F[i]) },
  name: { test: (i, v) => LNAME[i].includes(v), raw: i => F[i].name || '' },
  reason: { test: (i, v) => LREAS[i].includes(v), raw: i => F[i].reasons.join('\n') },
};
const ALIAS = { confidence: 'conf', category: 'cat', mod: 'module', reasons: 'reason', file: 'path' };
let queryError = false;
function parseQuery(q) {
  queryError = false;
  const tokens = q.match(/-?(?:[a-z]+:)?(?:"[^"]*"?|\/(?:\\.|[^\/\\])+\/[a-z]*|\S+)/gi) || [];
  const preds = [];
  for (let tok of tokens) {
    let neg = false;
    if (tok.length > 1 && tok[0] === '-') { neg = true; tok = tok.slice(1); }
    let field = null;
    const m = /^([a-z]+):(.*)$/i.exec(tok);
    if (m) { const name = ALIAS[m[1].toLowerCase()] || m[1].toLowerCase(); if (FIELD[name]) { field = FIELD[name]; tok = m[2]; } }
    if (tok.startsWith('"')) tok = tok.replace(/^"|"$/g, '');
    let p = null;
    const rx = /^\/(.+)\/([a-z]*)$/.exec(tok);
    if (rx) {
      let re; try { re = new RegExp(rx[1], rx[2].replace(/[gy]/g, '').includes('i') ? rx[2].replace(/[gy]/g, '') : rx[2].replace(/[gy]/g, '') + 'i'); } catch (e) { queryError = true; continue; }
      p = field ? (i => re.test(field.raw(i))) : (i => re.test(HAY[i]));
    } else {
      let v = tok.toLowerCase();
      if (!v) continue;
      if (field) { if (field.norm) v = field.norm(v); p = i => field.test(i, v); }
      else p = i => HAY[i].includes(v);
    }
    preds.push(neg ? (i => !p(i)) : p);
  }
  if (!preds.length) return null;
  if (preds.length === 1) return preds[0];
  return i => { for (const p of preds) if (!p(i)) return false; return true; };
}

// ---- state ----
const state = { q: '', sort: 'default', dir: 1 };
let pred = null, view = new Int32Array(0), facetCounts = null, active = -1, drawerIndex = -1, selVersion = 0;

function compute() {
  const t = performance.now();
  const anyIdx = [], selArr = [];
  FACETS.forEach((fc, k) => { if (fc.sel.size) { anyIdx.push(k); const a = new Uint8Array(fc.values.length); for (const v of fc.sel) if (fc.index.has(v)) a[fc.index.get(v)] = 1; selArr[k] = a; } });
  const counts = FACETS.map(fc => new Int32Array(fc.values.length));
  const mask = new Uint8Array(N);
  let total = 0, bytes = 0;
  for (let i = 0; i < N; i++) {
    if (pred && !pred(i)) continue;
    let miss = -1, nmiss = 0;
    for (const k of anyIdx) { if (!selArr[k][FACETS[k].codes[i]]) { miss = k; if (++nmiss > 1) break; } }
    if (nmiss === 0) {
      mask[i] = 1; total++; bytes += F[i].sizeBytes || 0;
      for (let k = 0; k < 4; k++) counts[k][FACETS[k].codes[i]]++;
    } else if (nmiss === 1) counts[miss][FACETS[miss].codes[i]]++;
  }
  const ord = order(state.sort === 'default' ? 'conf' : state.sort); // default: high first, then report order
  const out = new Int32Array(total);
  let j = 0;
  if (state.dir >= 0) { for (let x = 0; x < N; x++) if (mask[ord[x]]) out[j++] = ord[x]; }
  else { for (let x = N - 1; x >= 0; x--) if (mask[ord[x]]) out[j++] = ord[x]; }
  view = out; facetCounts = counts;
  timings.filter = performance.now() - t;
  return { total, bytes };
}

// ---- DOM refs ----
const scroller = $('#scroller'), tbody = $('#rows'), qInput = $('#q');
const ROW_H = 36, BUFFER = 12;

function apply(opts = {}) {
  const t = performance.now();
  const r = compute();
  $('#count').innerHTML = '<b>' + fmt(r.total) + '</b> of ' + fmt(N) + (r.bytes ? ' · ' + human(r.bytes) : '');
  $('#empty').hidden = view.length > 0;
  $('#tbl').setAttribute('aria-rowcount', String(view.length + 1));
  qInput.setAttribute('aria-invalid', queryError ? 'true' : 'false');
  updateFacets();
  renderChips();
  if (opts.selChanged !== false) { renderCharts(); renderGraph(); }
  if (opts.resetScroll !== false) { scroller.scrollTop = 0; active = view.length ? 0 : -1; }
  renderRows();
  for (const th of document.querySelectorAll('thead th')) {
    const key = th.dataset.sort;
    if (key === state.sort) th.setAttribute('aria-sort', state.dir >= 0 ? 'ascending' : 'descending'); else th.removeAttribute('aria-sort');
    th.querySelector('button').innerHTML = esc(th.textContent.replace(/[▲▼]/g, '').trim()) + (key === state.sort ? ' <span class="ar" aria-hidden="true">' + (state.dir >= 0 ? '▲' : '▼') + '</span>' : '');
  }
  writeHash();
  timings.apply = performance.now() - t;
  console.debug('[xcpurge] filter %sms, apply %sms, rows %d', timings.filter.toFixed(2), timings.apply.toFixed(2), view.length);
}

// ---- table ----
let rafPending = false;
function renderRows() {
  const n = view.length;
  const headH = 34;
  const top = Math.max(0, scroller.scrollTop);
  const h = scroller.clientHeight || 600;
  const start = Math.max(0, Math.floor(top / ROW_H) - BUFFER);
  const end = Math.min(n, Math.ceil((top + h - headH) / ROW_H) + BUFFER);
  let s = '';
  if (start > 0) s += '<tr class="spacer" aria-hidden="true"><td colspan="7" style="height:' + (start * ROW_H) + 'px"></td></tr>';
  for (let r = start; r < end; r++) {
    const i = view[r], f = F[i];
    const reasons = f.reasons;
    s += '<tr data-r="' + r + '" aria-rowindex="' + (r + 2) + '" tabindex="-1"' + (r === active ? ' class="active" aria-selected="true"' : '') + '>'
      + '<td><span class="kind"><i class="dot bg-' + esc(f.category) + '" aria-hidden="true"></i>' + esc(kebab(f.kind)) + '</span></td>'
      + '<td><span class="badge b-' + esc(f.confidence) + '">' + esc(f.confidence) + '</span></td>'
      + '<td class="mod" title="' + esc(f.module) + '">' + esc(f.module) + '</td>'
      + '<td title="' + esc(f.name || '') + '">' + (f.name ? esc(f.name) : '<span class="muted">—</span>') + '</td>'
      + '<td title="' + esc(loc(f)) + '"><span class="base">' + esc(base(f.path)) + (f.line != null ? ':' + f.line : '') + '</span><span class="dir">' + esc(dirOf(f.path)) + '</span></td>'
      + '<td class="num">' + (f.sizeBytes != null ? esc(human(f.sizeBytes)) : '<span class="muted">—</span>') + '</td>'
      + '<td class="reason" title="' + esc(reasons.join('\n')) + '">' + esc(reasons[0] || '') + (reasons.length > 1 ? '<span class="more">+' + (reasons.length - 1) + '</span>' : '') + '</td></tr>';
  }
  if (end < n) s += '<tr class="spacer" aria-hidden="true"><td colspan="7" style="height:' + ((n - end) * ROW_H) + 'px"></td></tr>';
  tbody.innerHTML = s;
}
scroller.addEventListener('scroll', () => { if (!rafPending) { rafPending = true; requestAnimationFrame(() => { rafPending = false; const had = scroller.contains(document.activeElement) && document.activeElement !== scroller; renderRows(); if (had) focusRow(false); }); } }, { passive: true });
function focusRow(scroll = true) {
  if (active < 0) return;
  if (scroll) {
    const top = active * ROW_H, vis = scroller.clientHeight - 34;
    if (top < scroller.scrollTop) scroller.scrollTop = top;
    else if (top + ROW_H > scroller.scrollTop + vis) scroller.scrollTop = top + ROW_H - vis;
    renderRows();
  }
  const el = tbody.querySelector('tr[data-r="' + active + '"]');
  if (el) el.focus({ preventScroll: true });
}
function setActive(r) {
  if (!view.length) return;
  active = Math.max(0, Math.min(view.length - 1, r));
  focusRow(true);
}
scroller.addEventListener('keydown', e => {
  if (!view.length) return;
  const page = Math.max(1, Math.floor((scroller.clientHeight - 34) / ROW_H) - 1);
  const map = { ArrowDown: 1, ArrowUp: -1, PageDown: page, PageUp: -page, j: 1, k: -1 };
  if (e.key in map) { e.preventDefault(); setActive(active < 0 ? 0 : active + map[e.key]); }
  else if (e.key === 'Home') { e.preventDefault(); setActive(0); }
  else if (e.key === 'End') { e.preventDefault(); setActive(view.length - 1); }
  else if (e.key === 'Enter' || e.key === ' ') { if (active >= 0) { e.preventDefault(); openDrawer(view[active]); } }
});
tbody.addEventListener('click', e => {
  const tr = e.target.closest('tr[data-r]');
  if (!tr) return;
  active = +tr.dataset.r; renderRows(); focusRow(false); openDrawer(view[active]);
});
document.querySelector('thead').addEventListener('click', e => {
  const th = e.target.closest('th[data-sort]'); if (!th) return;
  const key = th.dataset.sort;
  if (state.sort === key) state.dir = -state.dir; else { state.sort = key; state.dir = key === 'size' ? -1 : 1; }
  apply({ selChanged: false, resetScroll: true });
});

// ---- facets ----
const facetsEl = $('#facets');
facetsEl.innerHTML = FACETS.map((fc, k) => '<fieldset class="facet' + (fc.key === 'mod' ? ' mods' : '') + '"><h3>' + esc(fc.label) + '</h3><div class="opts">'
  + fc.values.map((v, j) => '<label class="opt" data-k="' + k + '" data-j="' + j + '"><input type="checkbox" data-k="' + k + '" data-j="' + j + '">'
    + (fc.key === 'conf' ? '<span class="badge b-' + esc(v) + '">' + esc(v) + '</span><span class="lbl"></span>'
      : fc.key === 'cat' ? '<i class="sw bg-' + esc(v) + '" aria-hidden="true"></i><span class="lbl">' + esc(v) + '</span>'
      : fc.key === 'kind' ? '<i class="dot bg-' + esc(kindCat[v]) + '" aria-hidden="true"></i><span class="lbl">' + esc(kebab(v)) + '</span>'
      : '<span class="lbl" title="' + esc(v) + '">' + esc(v) + '</span>')
    + '<span class="num"></span></label>').join('') + '</div></fieldset>').join('');
facetsEl.addEventListener('change', e => {
  const cb = e.target; if (!cb.dataset || cb.dataset.k == null) return;
  const fc = FACETS[+cb.dataset.k], v = fc.values[+cb.dataset.j];
  if (cb.checked) fc.sel.add(v); else fc.sel.delete(v);
  apply();
});
function updateFacets() {
  FACETS.forEach((fc, k) => {
    for (const lab of facetsEl.querySelectorAll('label[data-k="' + k + '"]')) {
      const j = +lab.dataset.j, c = facetCounts[k][j], v = fc.values[j];
      lab.querySelector('.num').textContent = fmt(c);
      lab.classList.toggle('zero', c === 0 && !fc.sel.has(v));
      lab.querySelector('input').checked = fc.sel.has(v);
    }
  });
}
function renderChips() {
  const chips = [];
  FACETS.forEach(fc => { for (const v of fc.sel) chips.push('<button type="button" class="chip" data-chip="' + fc.key + '" data-v="' + esc(v) + '" aria-label="Remove filter ' + esc(fc.label) + ' ' + esc(fc.show ? fc.show(v) : v) + '"><b>' + esc(fc.label.toLowerCase()) + '</b>' + esc(fc.show ? fc.show(v) : v) + ' ✕</button>'); });
  $('#chips').innerHTML = chips.join('');
}
$('#chips').addEventListener('click', e => {
  const b = e.target.closest('[data-chip]'); if (!b) return;
  FACETS.find(fc => fc.key === b.dataset.chip).sel.delete(b.dataset.v); apply();
});
$('#btn-clear').addEventListener('click', () => { FACETS.forEach(fc => fc.sel.clear()); qInput.value = ''; state.q = ''; pred = null; apply(); });
$('#btn-filters').addEventListener('click', e => { const on = $('#finder').classList.toggle('show-facets'); e.currentTarget.setAttribute('aria-expanded', String(on)); });

let debounce = 0;
qInput.addEventListener('input', () => {
  clearTimeout(debounce);
  debounce = setTimeout(() => { state.q = qInput.value; pred = parseQuery(state.q); apply({ selChanged: false, resetScroll: true }); }, 60);
});

// ---- charts ----
function setOnly(pairs) {
  const already = pairs.every(([key, v]) => { const fc = FACETS.find(f => f.key === key); return fc.sel.size === 1 && fc.sel.has(v); });
  for (const [key, v] of pairs) { const fc = FACETS.find(f => f.key === key); fc.sel.clear(); if (!already) fc.sel.add(v); }
  apply();
}
function chartWidth(el) { return Math.max(260, Math.floor(el.clientWidth || 360)); }
const isOn = (key, v) => FACETS.find(f => f.key === key).sel.has(v);
const isDim = (key, v) => { const fc = FACETS.find(f => f.key === key); return fc.sel.size > 0 && !fc.sel.has(v); };
function hbars(el, items, label) {
  if (!items.length) { el.innerHTML = '<p class="muted">Nothing to show.</p>'; return; }
  const w = chartWidth(el), labelW = Math.min(180, Math.round(w * 0.36)), valW = 72, barMax = Math.max(40, w - labelW - valW - 10);
  const rowH = 26, h = items.length * rowH;
  const max = Math.max(1, ...items.map(d => d.value));
  let s = '<svg width="' + w + '" height="' + h + '" role="group" aria-label="' + esc(label) + '">';
  items.forEach((d, i) => {
    const y = i * rowH, bw = Math.max(2, d.value / max * barMax);
    s += '<g class="hit' + (d.dim ? ' dim' : '') + '" tabindex="0" role="button" aria-pressed="' + !!d.on + '" data-set="' + esc(JSON.stringify(d.set)) + '" aria-label="' + esc(d.label + ': ' + d.text) + '">'
      + '<title>' + esc(d.label + ': ' + d.text) + '</title>'
      + '<rect x="0" y="' + y + '" width="' + (labelW + barMax + valW) + '" height="' + rowH + '" fill="transparent"/>'
      + '<text x="' + (labelW - 8) + '" y="' + (y + rowH / 2) + '" text-anchor="end" dominant-baseline="central">' + esc(trunc(d.label, (labelW - 10) / 6.6)) + '</text>'
      + '<rect class="track" x="' + labelW + '" y="' + (y + 5) + '" width="' + barMax + '" height="' + (rowH - 10) + '" rx="3"/>'
