  for (const f of F) for (const sv of dynSites(f)) { const k = sv.file + ':' + sv.line; sites.set(k, (sites.get(k) || 0) + 1); }
  const top = [...sites].sort((a, b) => b[1] - a[1] || cmpStr(a[0], b[0])).slice(0, 100);
  let s = '<div class="sub-h">Reported dynamic lookups (' + fmt(dynFindings.length) + ')</div>';
  s += dynFindings.length ? '<ul class="list">' + dynFindings.slice(0, 300).map(j => '<li><span class="grow"><button type="button" class="link" data-open="' + j + '">' + esc(loc(F[j])) + '</button>' + (F[j].name ? '<div class="muted mono">' + esc(F[j].name) + '</div>' : '') + '</span><span class="muted">' + esc(F[j].module) + '</span></li>').join('') + '</ul>' : '<p class="muted">None.</p>';
  s += '<div class="sub-h">Sites that downgraded findings (' + fmt(sites.size) + ')</div>';
  s += top.length ? '<ul class="list">' + top.map(([k, n]) => '<li><span class="grow"><button type="button" class="link" data-q="' + esc('"dynamically at ' + k + '"') + '">' + esc(k) + '</button></span><span class="num">' + fmt(n) + ' finding' + (n === 1 ? '' : 's') + '</span></li>').join('') + '</ul>' : '<p class="muted">None.</p>';
  $('#dyn').innerHTML = s;
  const diags = Array.isArray(D.diagnostics) ? D.diagnostics : [];
  const lv = { error: 'b-high', warning: 'b-medium', info: 'b-low' };
  $('#diag').innerHTML = diags.length ? '<ul class="list">' + diags.map(d => '<li><span class="badge ' + (lv[d.level] || 'b-plain') + '">' + esc(d.level) + '</span><span class="grow">' + (d.path ? '<code>' + esc(d.path) + '</code> ' : '') + esc(d.message) + '</span></li>').join('') + '</ul>' : '<p class="muted">No diagnostics.</p>';
}
$('#dyn').addEventListener('click', e => {
  const o = e.target.closest('[data-open]'); if (o) { openDrawer(+o.dataset.open); return; }
  const q = e.target.closest('[data-q]'); if (q) { qInput.value = q.dataset.q; state.q = q.dataset.q; pred = parseQuery(state.q); apply({ selChanged: false, resetScroll: true }); $('#h-findings').scrollIntoView({ behavior: 'smooth' }); }
});

// ---- header ----
let reclaim = 0; for (const f of F) if (f.confidence !== 'low' && f.sizeBytes) reclaim += f.sizeBytes;
$('#s-findings').textContent = fmt(N);
$('#s-bytes').textContent = human(reclaim);
$('#s-modules').textContent = fmt(MODULES.length);
const filesEl = $('#s-files'); filesEl.textContent = /^\d+$/.test(filesEl.textContent.trim()) ? fmt(+filesEl.textContent.trim()) : '—';
const dt = new Date($('#s-date').getAttribute('datetime'));
if (!isNaN(dt)) $('#s-date').textContent = dt.toLocaleString(undefined, { dateStyle: 'medium', timeStyle: 'short' });

let rT = 0, lastW = innerWidth;
addEventListener('resize', () => { if (innerWidth === lastW) return; lastW = innerWidth; clearTimeout(rT); rT = setTimeout(() => { renderCharts(); renderGraph(); renderRows(); }, 120); });

readHash();
renderLower();
apply({ resetScroll: true });
timings.firstRender = performance.now() - t0;
console.debug('[xcpurge] %d findings: parse %sms, index %sms, first render %sms', N, timings.parse.toFixed(1), timings.index.toFixed(1), timings.firstRender.toFixed(1));
window.xcpurge = { data: D, timings, state, search(q) { qInput.value = q; state.q = q; pred = parseQuery(q); const t = performance.now(); apply({ selChanged: false, resetScroll: true }); return { ms: performance.now() - t, filterMs: timings.filter, rows: view.length }; } };
})();
</script>
</body>
</html>

